def count_primes(N):
    count = 0
    for num in range(2, N + 1):
        is_prime = True
        for i in range(2, int(num**0.5) + 1):
            if num % i == 0:
                is_prime = False
                break
        if is_prime:
            count += 1
    return count

pi_50 = count_primes(50)
pi_51 = count_primes(51)

